import sys
from collections import defaultdict

def manacher(s):
    n = len(s)
    lps = [0] * n
    center = right = 0
    for i in range(n):
        mirror = 2 * center - i
        if i < right:
            lps[i] = min(right - i, lps[mirror])
        while i + lps[i] + 1 < n and i - lps[i] - 1 >= 0 and s[i + lps[i] + 1] == s[i - lps[i] - 1]:
            lps[i] += 1
        if i + lps[i] > right:
            center = i
            right = i + lps[i]
    return lps

def count_palindromes(s):
    n = len(s)
    lps_odd = manacher(s)
    lps_even = manacher("#" + "#".join(s) + "#")
    palindromes = set()
    for i in range(n):
        for j in range(1, lps_odd[i] + 1):
            palindromes.add(s[i - j + 1:i + j])
    for i in range(1, len(lps_even) - 1):
        if lps_even[i] % 2 == 0:
            palindromes.add(s[(i // 2) - (lps_even[i] // 2) + 1:(i // 2) + (lps_even[i] // 2)])
        else:
            palindromes.add(s[(i // 2) - ((lps_even[i] - 1) // 2):(i // 2) + ((lps_even[i] - 1) // 2) + 1])
    return palindromes

def count_decorations(T, N):
    palindromes = count_palindromes(T)
    dp = [[0] * (N + 1) for _ in range(len(palindromes) + 1)]
    for i in range(len(palindromes) + 1):
        dp[i][0] = 1
    for i in range(1, len(palindromes) + 1):
        for j in range(1, N + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, j + 1):
                dp[i][j] += dp[i - 1][j - k]
    unique_decorations = set()
    for i in range(1, len(palindromes) ** N + 1):
        decoration = []
        num = i - 1
        for j in range(N):
            decoration.append(list(palindromes)[num % len(palindromes)])
            num //= len(palindromes)
        decoration.sort()
        unique_decorations.add(tuple(decoration))
    return len(unique_decorations)

input = sys.stdin.read().split()
T = input[0]
N = int(input[1])
print(count_decorations(T, N))
